class Solution {
public:
    bool areNumbersAscending(string s) {
        int prev = 0;
        stringstream ss(s);
        string tok;
        while (ss >> tok) {
            if (isdigit(tok[0])) {
                int v = stoi(tok);
                if (v <= prev) return false;
                prev = v;
            }
        }
        return true;
    }
};

