class Solution {
    public boolean areNumbersAscending(String s) {
        int prev = 0;
        for (String tok : s.split(" ")) {
            if (Character.isDigit(tok.charAt(0))) {
                int v = Integer.parseInt(tok);
                if (v <= prev) return false;
                prev = v;
            }
        }
        return true;
    }
};

