class Solution:
    def areNumbersAscending(self, s: str) -> bool:
        prev = 0
        i, n = 0, len(s)
        while i < n:
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                v = int(s[i:j])
                if v <= prev:
                    return False
                prev = v
                i = j
            else:
                i += 1
        return True

