class Solution {
public:
    bool areNumbersAscending(string s) {
        int prev = 0, i = 0, n = s.size();
        while (i < n) {
            if (isdigit(s[i])) {
                int v = 0;
                while (i < n && isdigit(s[i])) v = v * 10 + (s[i++] - '0');
                if (v <= prev) return false;
                prev = v;
            } else {
                i++;
            }
        }
        return true;
    }
};

